async function v19ReportCanvas(r){const probe=document.createElement('canvas'),context=probe.getContext('2d');if(!context)throw Error('此浏览器未提供图片绘制功能，请选择HTML。');const lines=[];function wrap(text,title=false){context.font=title?'bold 24px sans-serif':'18px sans-serif';for(const paragraph of String(text||'').split('\n')){let line='';for(const char of Array.from(paragraph)){if(context.measureText(line+char).width>890){lines.push({text:line,title});line=''}line+=char}lines.push({text:line,title})}}
wrap('深雨知路 · RAINWISE',true);wrap(r.event,true);wrap('查询／资料时间：'+dateText(r.s.mode==='history'?r.s.at:r.s.created));wrap('导出时间：'+dateText(r.exported));for(const part of r.parts){wrap(part.title,true);wrap(part.text);lines.push({text:''})}
const visuals=[];if(r.s.scope==='weather'&&r.chosen.trend&&r.s.weather?.hourly){const rows=v12Hours(r.s.weather);for(const kind of ['temp','rain']){const svg=v12Chart(rows,kind);if(svg.startsWith('<svg'))visuals.push({image:await v19SvgImage(svg),width:900,height:900*276/760})}}if(r.chosen.map){const svg=vMapSvgSnapshot(r.s);if(svg.startsWith('<svg'))visuals.push({image:await v19SvgImage(svg),width:900,height:460})}if(r.chosen.photos)for(const f of r.s.feedbackRecords||[]){if(f.photo){const image=await v19Image(f.photo),scale=Math.min(900/image.width,420/image.height);visuals.push({image,width:image.width*scale,height:image.height*scale,caption:f.place+' · 用户图片 · '+dateText(f.observed)})}}
const height=100+lines.length*31+visuals.reduce((n,v)=>n+v.height+65,0);if(height>30000)throw Error('内容较长，建议选择HTML导出。');probe.width=1000;probe.height=Math.max(480,Math.ceil(height));const c=probe.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,probe.width,probe.height);let y=45;for(const line of lines){c.fillStyle=line.title?'#245f67':'#203644';c.font=line.title?'bold 24px sans-serif':'18px sans-serif';c.fillText(line.text,45,y);y+=31}for(const visual of visuals){c.drawImage(visual.image,45,y,visual.width,visual.height);y+=visual.height+25;if(visual.caption){c.font='15px sans-serif';c.fillStyle='#47616d';c.fillText(visual.caption,45,y)}y+=40}c.font='14px sans-serif';c.fillStyle='#617582';c.fillText('深雨知路 · 有来源的参考资料；不是官方预警或通行许可。',45,probe.height-25);return probe};
