const v19EnglishComplete=v18English;v18English=function(text){let t=v19EnglishComplete(text);for(const term of ['为家庭准备应急生活包','支持社区恢复与清理','让临时安置多一份温暖','交通受限','其他现场情况','公开新闻／公告（非本人观测）','立即出发','核验结论与回复','资料更新','页面生成','匹配结果','演示目标','模拟元','本地体验','回复：'])t=t.split(term).join(V18EN[term]);return t.replace(/(\d+)\s*个方案同时显示/g,'$1 options displayed').replace(/(\d+)\s*条/g,'$1 records').replace(/(\d+)\s*records本地评价/g,'$1 local ratings').replace(/ · 当前/g,' · Current').replace(/提交 (?=\d{4})/g,'Submitted ').replace(/ · 编号 /g,' · ID ').replace(/ · 观察 /g,' · Observed ').replace(/虚构演示发布者(\d+)/g,'Fictional publisher $1').replace(/的演示目标进度/g,' demo target progress')};
